/**
 * HTTP security headers for every static response, written to
 * dist/client/_headers at build time by src/integrations/security-headers.ts
 * (Cloudflare Workers static assets apply that file; responses generated by
 * Worker code do not get these headers). See ADR 0007.
 *
 * The Content-Security-Policy allows no inline code except the exact blocks
 * the build emits (the theme script, the cascade layer order, the font faces
 * and the no-JavaScript style), each by its SHA-256 hash.
 */

/** Third-party origins the pages may use, and why. */
export const ALLOWED_ORIGINS = {
  /** Cloudflare Web Analytics beacon script (when a token is configured). */
  analyticsScript: "https://static.cloudflareinsights.com",
  /** Where the analytics beacon reports page views. */
  analyticsReport: "https://cloudflareinsights.com",
  /** Cloudflare Turnstile script and challenge iframe (CV generator form). */
  turnstile: "https://challenges.cloudflare.com",
  /** Click-to-load YouTube player on project pages. */
  youtube: "https://www.youtube-nocookie.com",
} as const;

export interface InlineHashes {
  /** CSP hash sources such as `'sha256-...'` for inline scripts. */
  readonly scripts: readonly string[];
  /** CSP hash sources for inline `<style>` blocks. */
  readonly styles: readonly string[];
}

export type CspDirectives = Readonly<Record<string, readonly string[]>>;

/** The policy, with the build's inline hashes added to script-src and style-src. */
export function cspDirectives({ scripts, styles }: InlineHashes): CspDirectives {
  return {
    "default-src": ["'self'"],
    "script-src": [
      "'self'",
      ...scripts,
      ALLOWED_ORIGINS.analyticsScript,
      ALLOWED_ORIGINS.turnstile,
    ],
    "style-src": ["'self'", ...styles],
    "img-src": ["'self'", "data:"],
    "font-src": ["'self'"],
    "connect-src": ["'self'", ALLOWED_ORIGINS.analyticsReport],
    "frame-src": [ALLOWED_ORIGINS.youtube, ALLOWED_ORIGINS.turnstile],
    "frame-ancestors": ["'none'"],
    "base-uri": ["'self'"],
    "form-action": ["'self'"],
    "object-src": ["'none'"],
    "upgrade-insecure-requests": [],
  };
}

export function serializeCsp(directives: CspDirectives): string {
  return Object.entries(directives)
    .map(([name, sources]) => [name, ...sources].join(" "))
    .join("; ");
}

/** Every header for `/*`, in the order they are written. */
export function securityHeaders(hashes: InlineHashes): [name: string, value: string][] {
  return [
    ["Content-Security-Policy", serializeCsp(cspDirectives(hashes))],
    // No preload: the preload list is hard to leave, and subdomains are still being planned.
    ["Strict-Transport-Security", "max-age=31536000; includeSubDomains"],
    ["X-Content-Type-Options", "nosniff"],
    ["Referrer-Policy", "strict-origin-when-cross-origin"],
    // browsing-topics replaces the retired interest-cohort (FLoC).
    ["Permissions-Policy", "camera=(), microphone=(), geolocation=(), browsing-topics=()"],
    ["Cross-Origin-Opener-Policy", "same-origin"],
  ];
}

/** Cloudflare's limit for one line of `_headers`. */
export const HEADERS_LINE_LIMIT = 2000;

/** A `_headers` rule: the URL pattern, then one indented `Name: value` line per header. */
export function headersRule(pattern: string, headers: readonly [string, string][]): string {
  const lines = [pattern, ...headers.map(([name, value]) => `  ${name}: ${value}`)];
  const tooLong = lines.find((line) => line.length > HEADERS_LINE_LIMIT);
  if (tooLong) {
    throw new Error(
      `_headers line over ${HEADERS_LINE_LIMIT} characters (${tooLong.length}): ${tooLong.slice(0, 80)}...`,
    );
  }
  return `${lines.join("\n")}\n`;
}
